beforeExample:
import java.io.File;
import java.net.MalformedURLException;
import java.net.URL;

public class Example {
    public void processFile(File file) throws MalformedURLException {
        URL url = file.toURL();
        System.out.println(url);
    }
}

afterExample:
import java.io.File;
import java.net.MalformedURLException;
import java.net.URL;

public class Example {
    public void processFile(File file) throws MalformedURLException {
        URL url = file.toURI().toURL();
        System.out.println(url);
    }
}

